 "content": "def transform(grid):
    # Treat rows as signatures of their dominant horizontal pattern, collapsing
    # repeated background rows even where vertical marker colors interrupt them.
    # Every row with a repeated color across most columns is a horizontal stripe;
    # other rows are background/template rows.
    h, w = len(grid), len(grid[0])
    vertical_cols = {j for j in range(w) if len({grid[i][j] for i in range(h)}) > 1 and len(set(grid[i][j] for i in range(h))) <= 4}
    # Construct row sequence by collapsing consecutive rows with same pattern
    # after ignoring columns that form vertical lines.
    def sig(row):
        return tuple(v for j,v in enumerate(row) if j not in vertical_cols)
    rows=[]
    for row in grid:
        if not rows or sig(row) != sig(rows[-1]): rows.append(row[:])
    # Collapse adjacent identical column signatures after row reduction.
    cols=[]; prev=None
    for j in range(w):
        c=tuple(r[j] for r in rows)
        if c != prev: cols.append(j); prev=c
    return [[r[j] for j in cols] for r in rows]
"
}

